class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    i = 1
    while i < len(arr) and queue:
        node = queue.pop(0)
        if i < len(arr):
            left_val = arr[i]
            i += 1
            if left_val is not None:
                node.left = TreeNode(left_val)
                queue.append(node.left)
        if i < len(arr):
            right_val = arr[i]
            i += 1
            if right_val is not None:
                node.right = TreeNode(right_val)
                queue.append(node.right)
    return root


def diameter_of_binary_tree(root_arr):
    root = build_tree(root_arr)
    best = [0]

    def height(node):
        if node is None:
            return 0
        left_h = height(node.left)
        right_h = height(node.right)
        best[0] = max(best[0], left_h + right_h)
        return 1 + max(left_h, right_h)

    height(root)
    return best[0]

